    ('{"en":"Cinematic season","ko":"시네마틱 시즌"}'::jsonb,'{"en":"Teal & Orange, Golden Hour, Dark Cinema.","ko":"틸 & 오렌지, 골든 아워, 다크 시네마."}'::jsonb,'{"en":"Seasonal style","ko":"시즌 스타일"}'::jsonb,'#/discover?cat=cinematic',1,1,true),
    ('{"en":"Glitch & pixel lab","ko":"글리치 & 픽셀 랩"}'::jsonb,'{"en":"RGB split, dithering and ASCII for photo and video.","ko":"사진·영상용 RGB 분리, 디더링, 아스키."}'::jsonb,'{"en":"Popular effects","ko":"인기 효과"}'::jsonb,'#/discover?cat=glitch',2,2,true),
