-- announcements
  select '{"en":"Welcome to Lumora Studio","ko":"Lumora Studio에 오신 것을 환영합니다"}'::jsonb,'{"en":"Shoot with live filters, grade photos non-destructively and export videos — all in your browser.","ko":"실시간 필터 촬영, 비파괴 사진 보정, 영상 내보내기를 브라우저에서 바로 사용하세요."}'::jsonb,true where not exists (select 1 from public.announcements);

